import 'jsr:@supabase/functions-js/edge-runtime.d.ts'
import { createClient } from 'npm:@supabase/supabase-js@2.55.0'
const FPL_BASE='https://fantasy.premierleague.com/api'
function json(data:unknown,status=200){return new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8'}})}
Deno.serve(async(req:Request)=>{
 const publishableKeys=JSON.parse(Deno.env.get('SUPABASE_PUBLISHABLE_KEYS')||'{}'); const secretKeys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');
 const suppliedKey=req.headers.get('apikey'),allowedKey=publishableKeys.default; if(!allowedKey||suppliedKey!==allowedKey)return json({error:'unauthorized'},401); if(req.method!=='POST')return json({error:'POST required'},405);
 const adminKey=secretKeys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY'); if(!adminKey)return json({error:'server key unavailable'},500);
 const db=createClient(Deno.env.get('SUPABASE_URL')!,adminKey,{auth:{persistSession:false,autoRefreshToken:false}}); const now=new Date().toISOString();
 const {data:run,error:runErr}=await db.from('source_sync_runs').insert({source:'official_fpl',status:'running',metadata:{trigger:'edge-function'}}).select('id').single(); if(runErr)return json({error:`sync log start failed: ${runErr.message}`},500); const runId=run.id;
 try{
  const [bootstrapRes,fixturesRes]=await Promise.all([fetch(`${FPL_BASE}/bootstrap-static/`,{headers:{'user-agent':'Football-Intelligence-v0.1'}}),fetch(`${FPL_BASE}/fixtures/`,{headers:{'user-agent':'Football-Intelligence-v0.1'}})]);
  if(!bootstrapRes.ok)throw new Error(`bootstrap ${bootstrapRes.status}`); if(!fixturesRes.ok)throw new Error(`fixtures ${fixturesRes.status}`);
  const bootstrap=await bootstrapRes.json(),fixtures=await fixturesRes.json(); const currentEvent=bootstrap.events?.find((e:any)=>e.is_current)?.id??bootstrap.events?.find((e:any)=>e.is_next)?.id??1;
  const teams=(bootstrap.teams||[]).map((t:any)=>({fpl_team_id:t.id,team_code:t.code,name:t.name,short_name:t.short_name,strength:t.strength,updated_at:now}));
  let r=await db.from('teams').upsert(teams,{onConflict:'fpl_team_id'}); if(r.error)throw new Error(`teams upsert: ${r.error.message}`);
  const {data:dbTeams,error:teamMapErr}=await db.from('teams').select('id,fpl_team_id'); if(teamMapErr)throw teamMapErr; const teamMap=new Map((dbTeams||[]).map((t:any)=>[t.fpl_team_id,t.id])); const posMap=new Map((bootstrap.element_types||[]).map((p:any)=>[p.id,p.singular_name_short]));
  const players=(bootstrap.elements||[]).map((p:any)=>({fpl_player_id:p.id,player_code:p.code,team_id:teamMap.get(p.team)??null,first_name:p.first_name,second_name:p.second_name,web_name:p.web_name,position:posMap.get(p.element_type)??null,status:p.status,now_cost:p.now_cost,selected_by_percent:Number(p.selected_by_percent||0),updated_at:now}));
  r=await db.from('players').upsert(players,{onConflict:'fpl_player_id'}); if(r.error)throw new Error(`players upsert: ${r.error.message}`);
  const {data:dbPlayers,error:playerMapErr}=await db.from('players').select('id,fpl_player_id'); if(playerMapErr)throw playerMapErr; const playerMap=new Map((dbPlayers||[]).map((p:any)=>[p.fpl_player_id,p.id]));
  const priceRows=(bootstrap.elements||[]).map((p:any)=>({player_id:playerMap.get(p.id),captured_at:now,gameweek:currentEvent,price:p.now_cost,ownership:Number(p.selected_by_percent||0),transfers_in:p.transfers_in_event??0,transfers_out:p.transfers_out_event??0})).filter((p:any)=>p.player_id);
  r=await db.from('fpl_prices').insert(priceRows); if(r.error)throw new Error(`prices insert: ${r.error.message}`);
  const matchRows=(fixtures||[]).map((f:any)=>({fpl_fixture_id:f.id,gameweek:f.event,kickoff_time:f.kickoff_time,home_team_id:teamMap.get(f.team_h)??null,away_team_id:teamMap.get(f.team_a)??null,home_score:f.team_h_score,away_score:f.team_a_score,finished:Boolean(f.finished),source:'fpl',raw:f,updated_at:now}));
  r=await db.from('matches').upsert(matchRows,{onConflict:'fpl_fixture_id'}); if(r.error)throw new Error(`fixtures upsert: ${r.error.message}`);
  const counts={teams:teams.length,players:players.length,fixtures:matchRows.length,prices:priceRows.length,gameweek:currentEvent}; await db.from('source_sync_runs').update({finished_at:new Date().toISOString(),status:'success',rows_inserted:teams.length+players.length+matchRows.length+priceRows.length,metadata:counts}).eq('id',runId); return json({ok:true,...counts});
 }catch(e){const message=e instanceof Error?e.message:String(e); await db.from('source_sync_runs').update({finished_at:new Date().toISOString(),status:'failed',error:message}).eq('id',runId); return json({ok:false,error:message},500)}
})
